import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    if n == 1 or m == 1:
        # No teleporters needed for 1xN or Nx1 grid
        k = 0
        teleporters = []
        path = [(1, 1)]

        if n == 1:
            for y in range(2, m + 1):
                path.append((1, y))
            for y in range(m, 1, -1):
                path.append((1, y))
        else:
            for x in range(2, n + 1):
                path.append((x, 1))
            for x in range(n, 1, -1):
                path.append((x, 1))

        path.append((1, 1))
    else:
        # For larger grids, we need at least one teleporter
        k = 1
        teleporters = [(n, m, 1, 1)]
        path = [(1, 1)]

        # Move right to the last column
        for y in range(2, m + 1):
            path.append((1, y))

        # Move down to the last row
        for x in range(2, n + 1):
            path.append((x, m))

        # Use teleporter to go back to (1, 1)
        path.append((n, m))

        # Move left to the first column
        for y in range(m - 1, 0, -1):
            path.append((n, y))

        # Move up to the first row
        for x in range(n - 1, 0, -1):
            path.append((x, 1))

        # End at (1, 1)
        path.append((1, 1))

    # Output the result
    print(k)
    for t in teleporters:
        print(t[0], t[1], t[2], t[3])
    for p in path:
        print(p[0], p[1])

if __name__ == "__main__":
    main()
